#ifdef NAJA_ENABLE_SV_CONSTRUCTOR_PERF_REPORT
void setEnvVar(const char* name, const std::string& value) {
#if defined(_WIN32)
  _putenv_s(name, value.c_str());
#else
  setenv(name, value.c_str(), 1);
#endif
}

void unsetEnvVar(const char* name) {
#if defined(_WIN32)
  _putenv_s(name, "");
#else
  unsetenv(name);
#endif
}

class ScopedEnvVar {
  public:
    explicit ScopedEnvVar(const char* name):
      name_(name) {
      if (const char* value = std::getenv(name)) {
        previous_ = value;
      }
    }

    ~ScopedEnvVar() {
      if (previous_) {
        setEnvVar(name_.c_str(), *previous_);
      } else {
        unsetEnvVar(name_.c_str());
      }
    }

    void set(const std::string& value) const {
      setEnvVar(name_.c_str(), value);
    }

  private:
    std::string name_;
    std::optional<std::string> previous_;
};
#endif

class ScopedCurrentPath {
  public:
    explicit ScopedCurrentPath(const std::filesystem::path& path):
      previous_(std::filesystem::current_path()) {
      std::filesystem::current_path(path);
    }

    ~ScopedCurrentPath() {
      std::error_code ec;
      std::filesystem::current_path(previous_, ec);
    }

  private:
    std::filesystem::path previous_;
};

const SNLRTLInfos* getRTLInfos(const NLObject* object) {
  if (auto design = dynamic_cast<const SNLDesign*>(object)) {
    return design->getRTLInfos();
  }
  if (auto designObject = dynamic_cast<const SNLDesignObject*>(object)) {
    return designObject->getRTLInfos();
  }
  return nullptr;
}

bool hasRTLInfo(const NLObject* object, const std::string& name) {
  auto rtlInfos = getRTLInfos(object);
  return rtlInfos && rtlInfos->hasInfo(NLName(name));
}

std::string readTextFile(const std::filesystem::path& path) {
  std::ifstream file(path);
  std::stringstream buffer;
  buffer << file.rdbuf();
  return buffer.str();
}

std::filesystem::path writeSVTestFile(const std::string& testName, const std::string& text) {
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath /= testName;
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath = outPath / (testName + ".sv");
  std::ofstream svFile(svPath);
  EXPECT_TRUE(svFile.good());
  svFile << text;
  svFile.close();
  return svPath;
}

size_t countSubstring(const std::string& text, const std::string& needle) {
  if (needle.empty()) {
    return 0;
  }

  size_t count = 0;
  size_t pos = 0;
  while ((pos = text.find(needle, pos)) != std::string::npos) {
    ++count;
    pos += needle.size();
  }
  return count;
}

std::filesystem::path dumpTopAndGetVerilogPath(const SNLDesign* top,
                                               const std::string& outDirName,
                                               bool dumpRTLInfosAsAttributes = false,
                                               SNLVRLDumper::RTLInfoDumpMode rtlInfoDumpMode =
                                                 SNLVRLDumper::RTLInfoDumpMode::CompactAttribute) {
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath /= outDirName;
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  SNLVRLDumper dumper;
  auto fileName = top->getName().getString() + ".v";
  dumper.setTopFileName(fileName);
  dumper.setSingleFile(true);
  dumper.setDumpRTLInfosAsAttributes(dumpRTLInfosAsAttributes);
  if (dumpRTLInfosAsAttributes) {
    dumper.setRTLInfoDumpMode(rtlInfoDumpMode);
  }
  dumper.dumpDesign(top, outPath);
  return outPath / fileName;
}

SNLNet* getSingleAssignInputDriving(SNLBitNet* drivenNet) {
  if (!drivenNet) {
    ADD_FAILURE() << "Missing driven net";
    return nullptr;
  }

  std::vector<SNLInstance*> assignDrivers;
  for (auto* instTerm : drivenNet->getInstTerms()) {
    if (!instTerm || instTerm->getBitTerm() != NLDB0::getAssignOutput()) {
      continue;
    }
    auto* instance = instTerm->getInstance();
    if (instance && NLDB0::isAssign(instance->getModel())) {
      assignDrivers.push_back(instance);
    }
  }

  EXPECT_EQ(1u, assignDrivers.size()) << drivenNet->getString();
  if (assignDrivers.size() != 1) {
    return nullptr;
  }

  auto* inputTerm = assignDrivers.front()->getInstTerm(NLDB0::getAssignInput());
  if (!inputTerm) {
    ADD_FAILURE() << "Assign driver has no input term";
    return nullptr;
  }
  return inputTerm->getNet();
}

SNLNet* traceSingleAssignInputDriving(SNLNet* net) {
  auto* bitNet = dynamic_cast<SNLBitNet*>(net);
  if (!bitNet) {
    return net;
  }

  std::vector<SNLInstance*> assignDrivers;
  for (auto* instTerm : bitNet->getInstTerms()) {
    if (!instTerm || instTerm->getBitTerm() != NLDB0::getAssignOutput()) {
      continue;
    }
    auto* instance = instTerm->getInstance();
    if (instance && NLDB0::isAssign(instance->getModel())) {
      assignDrivers.push_back(instance);
    }
  }

  if (assignDrivers.size() != 1) {
    return net;
  }

  auto* inputTerm = assignDrivers.front()->getInstTerm(NLDB0::getAssignInput());
  if (!inputTerm) {
    return net;
  }
  return inputTerm->getNet();
}

bool haveEquivalentFanIn(
    SNLBitNet* lhs,
    SNLBitNet* rhs,
    std::set<std::pair<SNLBitNet*, SNLBitNet*>>& visited) {
  if (!lhs || !rhs) {
    return lhs == rhs;
  }
  lhs = dynamic_cast<SNLBitNet*>(traceSingleAssignInputDriving(lhs));
  rhs = dynamic_cast<SNLBitNet*>(traceSingleAssignInputDriving(rhs));
  if (!lhs || !rhs) {
    return lhs == rhs;
  }
  if (lhs == rhs) {
    return true;
  }
  if (lhs->isConstant() || rhs->isConstant()) {
    return lhs->getType() == rhs->getType();
  }
  if (!visited.emplace(lhs, rhs).second) {
    return true;
  }

  auto findDriver = [](SNLBitNet* net) -> SNLInstance* {
    SNLInstance* driver = nullptr;
    for (auto* instTerm : net->getInstTerms()) {
      if (!instTerm || instTerm->getDirection() != SNLTerm::Direction::Output) {
        continue;
      }
      if (driver && driver != instTerm->getInstance()) {
        return nullptr;
      }
      driver = instTerm->getInstance();
    }
    return driver;
  };

  auto* lhsDriver = findDriver(lhs);
  auto* rhsDriver = findDriver(rhs);
  if (!lhsDriver || !rhsDriver || lhsDriver->getModel() != rhsDriver->getModel()) {
    return false;
  }
  for (auto* lhsInput : lhsDriver->getInstTerms()) {
    if (!lhsInput || lhsInput->getDirection() != SNLTerm::Direction::Input) {
      continue;
    }
    auto* rhsInput = rhsDriver->getInstTerm(lhsInput->getBitTerm());
    if (!rhsInput) {
      return false;
    }
    auto* lhsInputNet = dynamic_cast<SNLBitNet*>(lhsInput->getNet());
    auto* rhsInputNet = dynamic_cast<SNLBitNet*>(rhsInput->getNet());
    if (!haveEquivalentFanIn(lhsInputNet, rhsInputNet, visited)) {
      return false;
    }
  }
  return true;
}

bool haveEquivalentFanIn(SNLBitNet* lhs, SNLBitNet* rhs) {
  std::set<std::pair<SNLBitNet*, SNLBitNet*>> visited;
  return haveEquivalentFanIn(lhs, rhs, visited);
}

size_t getPrimitiveWidth(const SNLInstance* instance) {
  if (!instance) {
    return 0;
  }
  if (auto* widthInstParam = instance->getInstParameter(NLName("WIDTH"))) {
    return static_cast<size_t>(std::stoull(widthInstParam->getValue()));
  }
  auto* model = instance->getModel();
  if (!model) {
    return 0;
  }
  if (auto* widthParam = model->getParameter(NLName("WIDTH"))) {
    return static_cast<size_t>(std::stoull(widthParam->getValue()));
  }
  return 1;
}

using PrimitivePredicate = bool (*)(const SNLDesign*);

const SNLInstance* findOnlyPrimitiveInstance(
  const SNLDesign* design,
  PrimitivePredicate predicate) {
  const SNLInstance* found = nullptr;
  for (auto* inst : design->getInstances()) {
    auto* model = inst ? inst->getModel() : nullptr;
    if (!model || !predicate(model)) {
      continue;
    }
    if (found) {
      ADD_FAILURE() << "Found more than one matching primitive instance";
      return found;
    }
    found = inst;
  }
  return found;
}

size_t countPrimitiveBits(
    const SNLDesign* design,
    std::initializer_list<PrimitivePredicate> predicates) {
  size_t count = 0;
  if (!design) {
    return count;
  }
  for (auto* inst : design->getInstances()) {
    auto* model = inst ? inst->getModel() : nullptr;
    if (!model) {
      continue;
    }
    for (auto predicate : predicates) {
      if (predicate && predicate(model)) {
        count += getPrimitiveWidth(inst);
        break;
      }
    }
  }
  return count;
}

size_t countPrimitiveBits(
    const SNLDesign* design,
    PrimitivePredicate predicate) {
  return countPrimitiveBits(design, {predicate});
}

size_t countPrimitiveInstances(
    const SNLDesign* design,
    PrimitivePredicate predicate) {
  size_t count = 0;
  if (!design) {
    return count;
  }
  for (auto* inst : design->getInstances()) {
    auto* model = inst ? inst->getModel() : nullptr;
    if (predicate && predicate(model)) {
      ++count;
    }
  }
  return count;
}

size_t countDFFBits(const SNLDesign* design) {
  return countPrimitiveBits(design, NLDB0::isDFF);
}

size_t countAssignXNets(const SNLDesign* design) {
  size_t count = 0;
  for (auto* net : design->getScalarNets()) {
    count += net->isAssignX();
  }
  return count;
}

