TEST_F(
  SNLSVConstructorTestSimple,
  parseAlwaysCombConditionalLogicalShortcutsSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath = outPath / "always_comb_conditional_logical_shortcuts_supported";
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath = outPath / "always_comb_conditional_logical_shortcuts_supported.sv";
  std::ofstream svFile(svPath);
  ASSERT_TRUE(svFile.good());
  svFile
    << R"(module always_comb_conditional_logical_shortcuts_supported(
  input  logic a_i,
  input  logic b_i,
  output logic y0_o,
  output logic y1_o,
  output logic y2_o,
  output logic y3_o,
  output logic y4_o,
  output logic y5_o
);
  always_comb begin
    y0_o = 1'b0;
    if (!(a_i && 1'b0)) begin
      y0_o = 1'b1;
    end
  end

  always_comb begin
    y1_o = 1'b0;
    if (!(a_i || 1'b1)) begin
      y1_o = 1'b1;
    end
  end

  always_comb begin
    y2_o = 1'b0;
    if ((a_i && 1'b0) && b_i) begin
      y2_o = 1'b1;
    end
  end

  always_comb begin
    y3_o = 1'b0;
    if ((a_i || 1'b1) || b_i) begin
      y3_o = 1'b1;
    end
  end

  always_comb begin
    y4_o = 1'b0;
    if ((a_i && 1'b0) || b_i) begin
      y4_o = 1'b1;
    end
  end

  always_comb begin
    y5_o = 1'b0;
    if (a_i || 1'b0) begin
      y5_o = 1'b1;
    end
  end
endmodule
)";
  svFile.close();

  constructor.construct(svPath);

  auto top =
    library_->getSNLDesign(NLName("always_comb_conditional_logical_shortcuts_supported"));
  ASSERT_NE(top, nullptr);
  EXPECT_NE(top->getNet(NLName("y0_o")), nullptr);
  EXPECT_NE(top->getNet(NLName("y5_o")), nullptr);
}

TEST_F(
  SNLSVConstructorTestSimple,
  parseSequentialEnableCondTernaryShortcutsSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath = outPath / "seq_enable_cond_ternary_shortcuts_supported";
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath =
    outPath / "seq_enable_cond_ternary_shortcuts_supported.sv";
  std::ofstream svFile(svPath);
  ASSERT_TRUE(svFile.good());
  svFile
    << R"(module seq_enable_cond_ternary_shortcuts_supported(
  input  logic clk_i,
  input  logic rst_ni,
  input  logic a_i,
  input  logic b_i,
  input  logic c_i,
  input  logic d_i,
  output logic known_o,
  output logic true_o,
  output logic false_o,
  output logic same_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) known_o <= 1'b0;
    else if (1'b1 ? a_i : b_i) known_o <= d_i;
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) true_o <= 1'b0;
    else if ((a_i | 1'b1) ? b_i : c_i) true_o <= d_i;
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) false_o <= 1'b0;
    else if ((a_i & 1'b0) ? b_i : c_i) false_o <= d_i;
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) same_o <= 1'b0;
    else if (a_i ? b_i : b_i) same_o <= d_i;
  end
endmodule
)";
  svFile.close();

  constructor.construct(svPath);

  auto top = library_->getSNLDesign(NLName("seq_enable_cond_ternary_shortcuts_supported"));
  ASSERT_NE(top, nullptr);
  EXPECT_NE(top->getNet(NLName("known_o")), nullptr);
  EXPECT_NE(top->getNet(NLName("true_o")), nullptr);
  EXPECT_NE(top->getNet(NLName("false_o")), nullptr);
  EXPECT_NE(top->getNet(NLName("same_o")), nullptr);
}

TEST_F(
  SNLSVConstructorTestSimple,
  parseCoverage2SequentialIgnorableBranchNoAssignmentSupported) {
  // The if-branch only contains ignorable system tasks and assigns nothing, so
  // q_o holds its value when en_i is set and loads d_i otherwise. This lowers
  // to q_o <= en_i ? q_o : d_i, i.e. a feedback mux feeding a DFF.
  SNLSVConstructor constructor(library_);
  const auto svPath = writeSVTestFile(
    "coverage2_sequential_ignorable_branch_no_assignment_supported",
    R"(module coverage2_sequential_ignorable_branch_no_assignment_supported(
  input  logic clk_i,
  input  logic en_i,
  input  logic d_i,
  output logic q_o
);
  always_ff @(posedge clk_i) begin
    if (en_i) begin
      $display("ignored");
      $info("also ignored");
    end else begin
      q_o <= d_i;
    end
  end
endmodule
)");

  constructor.construct(svPath);
  auto top = library_->getSNLDesign(
    NLName("coverage2_sequential_ignorable_branch_no_assignment_supported"));
  ASSERT_NE(top, nullptr);
  EXPECT_NE(top->getNet(NLName("q_o")), nullptr);

  size_t dffCount = 0;
  for (auto inst : top->getInstances()) {
    if (NLDB0::isDFF(inst->getModel())) {
      dffCount += getPrimitiveWidth(inst);
    }
  }
  EXPECT_EQ(1u, dffCount);
  EXPECT_GE(countMux2Instances(top), 1u);
}

