TEST_F(
  SNLSVConstructorTestSimple,
  parseSequentialMultiAssignmentNestedGuardedBlockSkipsUnrelatedBranches) {
  // Generated reset/update blocks can contain a shared synchronous branch that
  // touches every register and an else branch with many one-register guarded
  // updates. Replaying every unrelated guard for every LHS scales badly and
  // emits redundant muxes.
  SNLSVConstructor constructor(library_);
  const auto svPath = writeSVTestFile(
    "seq_multi_assignment_nested_guarded_block_skips_unrelated_branches",
    R"(module seq_multi_assignment_nested_guarded_block_skips_unrelated_branches(
  input  logic clk,
  input  logic rst,
  input  logic clear,
  input  logic en0,
  input  logic en1,
  input  logic en2,
  input  logic en3,
  input  logic d0,
  input  logic d1,
  input  logic d2,
  input  logic d3,
  output logic q0,
  output logic q1,
  output logic q2,
  output logic q3
);
  always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
    end else begin
      if (clear) begin
        q0 <= 1'b0;
        q1 <= 1'b0;
        q2 <= 1'b0;
        q3 <= 1'b0;
      end else begin
        if (en0)
          q0 <= d0;
        if (en1)
          q1 <= d1;
        if (en2)
          q2 <= d2;
        if (en3)
          q3 <= d3;
      end
    end
  end
endmodule
)");

  constructor.construct(svPath);

  auto top = library_->getSNLDesign(
    NLName("seq_multi_assignment_nested_guarded_block_skips_unrelated_branches"));
  ASSERT_NE(top, nullptr);

  EXPECT_EQ(0u, countDFFBits(top));
  EXPECT_EQ(4u, countDFFRBits(top));
  EXPECT_EQ(8u, countMux2Instances(top));
}

TEST_F(
  SNLSVConstructorTestSimple,
  parseSequentialMultibitOneBitLiteralRHSExtendsWithZeros) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath = outPath / "seq_multibit_one_bit_literal_rhs_extends_with_zeros";
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath =
    outPath / "seq_multibit_one_bit_literal_rhs_extends_with_zeros.sv";
  std::ofstream svFile(svPath);
  ASSERT_TRUE(svFile.good());
  svFile
    << R"(module seq_multibit_one_bit_literal_rhs_extends_with_zeros(
  input  logic       clk_i,
  output logic [1:0] q_based_o,
  output logic [1:0] q_sized_o,
  output logic [1:0] q_unbased_o
);
  always_ff @(posedge clk_i) begin
    q_based_o   <= 'b1;
    q_sized_o   <= 1'b1;
    q_unbased_o <= '1;
  end
endmodule
)";
  svFile.close();

  constructor.construct(svPath);

  auto top = library_->getSNLDesign(
    NLName("seq_multibit_one_bit_literal_rhs_extends_with_zeros"));
  ASSERT_NE(top, nullptr);

  auto* qBased = top->getBusNet(NLName("q_based_o"));
  auto* qSized = top->getBusNet(NLName("q_sized_o"));
  auto* qUnbased = top->getBusNet(NLName("q_unbased_o"));
  ASSERT_NE(qBased, nullptr);
  ASSERT_NE(qSized, nullptr);
  ASSERT_NE(qUnbased, nullptr);

  auto* qBased0Data = traceSingleAssignInputDriving(
    getDFFDataForOutputBit(top, qBased->getBit(0)));
  auto* qBased1Data = traceSingleAssignInputDriving(
    getDFFDataForOutputBit(top, qBased->getBit(1)));
  auto* qSized0Data = traceSingleAssignInputDriving(
    getDFFDataForOutputBit(top, qSized->getBit(0)));
  auto* qSized1Data = traceSingleAssignInputDriving(
    getDFFDataForOutputBit(top, qSized->getBit(1)));
  auto* qUnbased0Data = traceSingleAssignInputDriving(
    getDFFDataForOutputBit(top, qUnbased->getBit(0)));
  auto* qUnbased1Data = traceSingleAssignInputDriving(
    getDFFDataForOutputBit(top, qUnbased->getBit(1)));
  ASSERT_NE(qBased0Data, nullptr);
  ASSERT_NE(qBased1Data, nullptr);
  ASSERT_NE(qSized0Data, nullptr);
  ASSERT_NE(qSized1Data, nullptr);
  ASSERT_NE(qUnbased0Data, nullptr);
  ASSERT_NE(qUnbased1Data, nullptr);

  EXPECT_TRUE(qBased0Data->isAssign1());
  EXPECT_TRUE(qBased1Data->isAssign0());
  EXPECT_TRUE(qSized0Data->isAssign1());
  EXPECT_TRUE(qSized1Data->isAssign0());
  EXPECT_TRUE(qUnbased0Data->isAssign1());
  EXPECT_TRUE(qUnbased1Data->isAssign1());
}

TEST_F(SNLSVConstructorTestSimple, parseUnaryNotCreatesNOutputGate) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path benchmarksPath(SNL_SV_BENCHMARKS_PATH);
  constructor.construct(benchmarksPath / "unary_not" / "unary_not.sv");

  auto top = library_->getSNLDesign(NLName("unary_not_top"));
  ASSERT_NE(top, nullptr);

  size_t notGateCount = 0;
  size_t assignCount = 0;
  for (auto inst : top->getInstances()) {
    if (NLDB0::isAssign(inst->getModel())) {
      ++assignCount;
      continue;
    }
    if (NLDB0::isGate(inst->getModel()) &&
        NLDB0::getGateName(inst->getModel()) == "not") {
      ++notGateCount;
    }
  }

  EXPECT_EQ(1u, notGateCount);
  EXPECT_EQ(1u, assignCount);

  auto dumpedVerilog = dumpTopAndGetVerilogPath(top, "unary_not");
  EXPECT_TRUE(std::filesystem::exists(dumpedVerilog));
}

TEST_F(SNLSVConstructorTestSimple, parseUnaryNotOnBinaryOperatorsSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path benchmarksPath(SNL_SV_BENCHMARKS_PATH);
  constructor.construct(
    benchmarksPath / "unary_not_binary_supported" / "unary_not_binary_supported.sv");

  auto top = library_->getSNLDesign(NLName("unary_not_binary_supported_top"));
  ASSERT_NE(top, nullptr);
  const std::array<const char*, 3> outputs{
    "y_nand",
    "y_nor",
    "y_xnor"};
  for (const auto* output : outputs) {
    auto net = top->getNet(NLName(output));
    ASSERT_NE(net, nullptr);
    auto bitNet = dynamic_cast<SNLBitNet*>(net);
    ASSERT_NE(bitNet, nullptr);
    EXPECT_FALSE(bitNet->getInstTerms().empty());
  }

  size_t nandGateCount = 0;
  size_t norGateCount = 0;
  size_t xnorGateCount = 0;
  size_t otherGateCount = 0;
  size_t assignCount = 0;
  for (auto inst : top->getInstances()) {
    if (NLDB0::isAssign(inst->getModel())) {
      ++assignCount;
      continue;
    }
    if (!NLDB0::isGate(inst->getModel())) {
      continue;
    }
    auto gateName = NLDB0::getGateName(inst->getModel());
    if (gateName == "nand") {
      ++nandGateCount;
    } else if (gateName == "nor") {
      ++norGateCount;
    } else if (gateName == "xnor") {
      ++xnorGateCount;
    } else {
      ++otherGateCount;
    }
  }

  EXPECT_EQ(1u, nandGateCount);
  EXPECT_EQ(1u, norGateCount);
  EXPECT_EQ(1u, xnorGateCount);
  EXPECT_EQ(0u, otherGateCount);
  EXPECT_EQ(outputs.size(), assignCount);

  auto dumpedVerilog = dumpTopAndGetVerilogPath(top, "unary_not_binary_supported");
  EXPECT_TRUE(std::filesystem::exists(dumpedVerilog));
}

