  size_t ffCount = 0;
  auto dffModel = NLDB0::getDFF();
  auto dffrnModel = NLDB0::getDFFRN();
  for (auto inst : top->getInstances()) {
    if ((dffModel && NLDB0::isDFF(inst->getModel())) ||
        (dffrnModel && NLDB0::isDFFRN(inst->getModel()))) {
        ffCount += getPrimitiveWidth(inst);
    }
  }
