TEST_F(
  SNLSVConstructorTestSimple,
  parseSequentialEnableCondLogicalAndLHSCallFallbackSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath = outPath / "seq_enable_cond_logical_and_lhs_call_fallback_supported";
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath =
    outPath / "seq_enable_cond_logical_and_lhs_call_fallback_supported.sv";
  std::ofstream svFile(svPath);
  ASSERT_TRUE(svFile.good());
  svFile
    << R"(module seq_enable_cond_logical_and_lhs_call_fallback_supported(
  input  logic       clk_i,
  input  logic       rst_ni,
  input  logic [3:0] a_i,
  input  logic       d_i,
  output logic       q_o
);
  function automatic logic bad_cond(input logic [3:0] op_i);
    case (op_i) inside
      [4'bxxxx : 4'd7]: bad_cond = 1'b1;
      default:          bad_cond = 1'b0;
    endcase
  endfunction
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) begin
      q_o <= 1'b0;
    end else if (bad_cond(a_i) && d_i) begin
      q_o <= d_i;
    end
  end
endmodule
)";
  svFile.close();

  // bad_cond() is a 1-bit Call whose result cannot be synthesised; the
  // resolveSingleBitExpression() fallback now treats it as constant-false so
  // the else-if branch is statically not taken → construction succeeds.
  EXPECT_NO_THROW(constructor.construct(svPath));
  auto top = SNLUtils::findTop(library_);
  ASSERT_NE(nullptr, top);
  // q_o is always driven by the reset branch (constant 0).
  EXPECT_NE(top->getNet(NLName("q_o")), nullptr);
}

TEST_F(
  SNLSVConstructorTestSimple,
  parseSequentialEnableCondLogicalAndRHSCallFallbackSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath = outPath / "seq_enable_cond_logical_and_rhs_call_fallback_supported";
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath =
    outPath / "seq_enable_cond_logical_and_rhs_call_fallback_supported.sv";
  std::ofstream svFile(svPath);
  ASSERT_TRUE(svFile.good());
  svFile
    << R"(module seq_enable_cond_logical_and_rhs_call_fallback_supported(
  input  logic       clk_i,
  input  logic       rst_ni,
  input  logic       en_i,
  input  logic [3:0] a_i,
  input  logic       d_i,
  output logic       q_o
);
  function automatic logic bad_cond(input logic [3:0] op_i);
    case (op_i) inside
      [4'bxxxx : 4'd7]: bad_cond = 1'b1;
      default:          bad_cond = 1'b0;
    endcase
  endfunction
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) begin
      q_o <= 1'b0;
    end else if (en_i && bad_cond(a_i)) begin
      q_o <= d_i;
    end
  end
endmodule
)";
  svFile.close();

  // en_i && bad_cond(a_i): bad_cond is an unresolvable 1-bit Call — treated as
  // constant-false, so the else-if branch is statically not taken → succeeds.
  EXPECT_NO_THROW(constructor.construct(svPath));
  auto top = SNLUtils::findTop(library_);
  ASSERT_NE(nullptr, top);
  EXPECT_NE(top->getNet(NLName("q_o")), nullptr);
}

TEST_F(SNLSVConstructorTestSimple, parseSequentialEnableCondLogicalShortcutsSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path outPath(SNL_SV_DUMPER_TEST_PATH);
  outPath = outPath / "seq_enable_cond_logical_shortcuts_supported";
  if (std::filesystem::exists(outPath)) {
    std::filesystem::remove_all(outPath);
  }
  std::filesystem::create_directory(outPath);

  const auto svPath = outPath / "seq_enable_cond_logical_shortcuts_supported.sv";
  std::ofstream svFile(svPath);
  ASSERT_TRUE(svFile.good());
  svFile
    << R"(module seq_enable_cond_logical_shortcuts_supported(
  input  logic       clk_i,
  input  logic       rst_ni,
  input  logic       a_i,
  input  logic       b_i,
  input  logic       d_i,
  output logic       q0_o,
  output logic       q1_o,
  output logic       q2_o,
  output logic       q3_o,
  output logic       q4_o,
  output logic       q5_o,
  output logic       q6_o,
  output logic       q7_o,
  output logic       q8_o,
  output logic       q9_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q0_o <= 1'b0;
    else if ((a_i && 1'b0) && b_i) q0_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q1_o <= 1'b0;
    else if ((a_i || 1'b1) || b_i) q1_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q2_o <= 1'b0;
    else if (a_i && 1'b0) q2_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q3_o <= 1'b0;
    else if (1'b1 && a_i) q3_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q4_o <= 1'b0;
    else if (a_i && 1'b1) q4_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q5_o <= 1'b0;
    else if (a_i && a_i) q5_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q6_o <= 1'b0;
    else if (a_i || 1'b1) q6_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q7_o <= 1'b0;
    else if (1'b0 || a_i) q7_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q8_o <= 1'b0;
    else if (a_i || 1'b0) q8_o <= d_i;
  end
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (rst_ni === 1'b0) q9_o <= 1'b0;
    else if (a_i || a_i) q9_o <= d_i;
  end
endmodule
)";
  svFile.close();

  constructor.construct(svPath);

  auto top = library_->getSNLDesign(NLName("seq_enable_cond_logical_shortcuts_supported"));
  ASSERT_NE(top, nullptr);
  EXPECT_NE(top->getNet(NLName("q0_o")), nullptr);
  EXPECT_NE(top->getNet(NLName("q9_o")), nullptr);
}

