TEST_F(SNLSVConstructorTestSimple, parseSequentialEnableActionSupported) {
  SNLSVConstructor constructor(library_);
  std::filesystem::path benchmarksPath(SNL_SV_BENCHMARKS_PATH);
  constructor.construct(
    benchmarksPath / "seq_enable_action_supported" / "seq_enable_action_supported.sv");

  auto top = library_->getSNLDesign(NLName("seq_enable_action_supported"));
  ASSERT_NE(top, nullptr);

  auto dffModel = NLDB0::getDFF();
  ASSERT_NE(dffModel, nullptr);
  size_t addSubCount = 0;
  size_t dffCount = 0;
  for (auto inst : top->getInstances()) {
    if (isSequentialDFFPrimitive(inst->getModel())) {
      dffCount += getPrimitiveWidth(inst);
    }
    if (NLDB0::isAddSub(inst->getModel())) {
      ++addSubCount;
    }
  }
  EXPECT_EQ(8u, dffCount);
  EXPECT_GT(addSubCount, 0u);
}

