TEST_F(SNLSVConstructorTestSimple, wideAndSignedIndexFourStateSimulation) {
  const auto path = writeSVTestFile("wide_signed_index_reads", R"(
module wide_signed_index_reads(input logic [63:0] data,
                               input logic [39:0] wide_index,
                               input logic signed [5:0] signed_index,
                               input logic signed [1:0] small_index,
                               output logic wide_bit, signed_bit, unsigned_bit,
                               output logic small_signed_bit,
                               output logic [3:0] ascending_word);
  wire [0:15][3:0] words = data;
  assign wide_bit = data[wide_index];
  assign signed_bit = data[signed_index];
  assign unsigned_bit = data[$unsigned(signed_index)];
  assign small_signed_bit = data[small_index];
  assign ascending_word = words[wide_index];
endmodule
)");
  SNLSVConstructor(library_).construct(path);
  auto* top = library_->getSNLDesign(NLName("wide_signed_index_reads"));
  ASSERT_NE(nullptr, top);
  EXPECT_EQ(1u, countTableSelectInstances(
    top, NLDB0::TableSelectSignature {1, 64, 40}));
  EXPECT_EQ(2u, countTableSelectInstances(
    top, NLDB0::TableSelectSignature {1, 64, 7}));
  EXPECT_EQ(1u, countTableSelectInstances(
    top, NLDB0::TableSelectSignature {1, 64, 6}));
  EXPECT_EQ(1u, countTableSelectInstances(
    top, NLDB0::TableSelectSignature {4, 16, 40}));
  const auto dumped = dumpTopAndGetVerilogPath(top, "wide_signed_index_reads_dump");
  if (std::system("command -v iverilog >/dev/null 2>&1") ||
      std::system("command -v vvp >/dev/null 2>&1")) {
    GTEST_SKIP() << "Icarus Verilog is required for the four-state comparison";
  }
  const auto tbPath = dumped.parent_path() / "tb.sv";
  std::ofstream tb(tbPath);
  tb << R"(module tb;
  reg [63:0] data;
  reg [39:0] wide_index;
  reg signed [5:0] signed_index;
  wire signed [1:0] small_index = signed_index[1:0];
  wire wide_bit, signed_bit, unsigned_bit;
  wire small_signed_bit;
  wire [3:0] ascending_word;
  wire [0:15][3:0] words = data;
  // Icarus truncates packed indices above 32 bits; check their bounds explicitly.
  wire expected_wide = wide_index < 64 ? data[wide_index] : 1'bx;
  wire [3:0] expected_word = wide_index < 16 ? words[wide_index] : 4'bxxxx;
  wide_signed_index_reads dut(.*);
  task check;
    begin
      #1;
      if (wide_bit !== expected_wide ||
          signed_bit !== data[signed_index] ||
          unsigned_bit !== data[$unsigned(signed_index)] ||
          small_signed_bit !== data[small_index] ||
          ascending_word !== expected_word)
        $fatal(1, "index mismatch wide=%h signed=%d", wide_index, signed_index);
    end
  endtask
  integer pattern, index;
  initial begin
    for (pattern = 0; pattern < 5; pattern = pattern + 1) begin
      case (pattern)
        0: data = '0;
        1: data = '1;
        2: data = 64'h93a5_0f6c_d281_7be4;
        3: data = 'x;
        4: data = 'z;
      endcase
      for (index = 0; index < 70; index = index + 1) begin
        wide_index = index; signed_index = index; check;
      end
      // High address bits must not alias a valid low address.
      wide_index = 40'h8000000003; signed_index = -1; check;
      wide_index = '1; signed_index = -32; check;
      wide_index = 'x; signed_index = 'x; check;
      wide_index = 'z; signed_index = 'z; check;
      wide_index = 40'b0x; signed_index = 6'b0x; check;
    end
    $finish;
  end
endmodule
)";
  tb.close();
  const auto quote = [](const std::filesystem::path& p) {
    std::string result = "'";
    for (char c: p.string()) result += c == '\'' ? "'\\''" : std::string(1, c);
    return result + "'";
  };
  const auto executable = dumped.parent_path() / "simulation.vvp";
  const auto compile = "iverilog -g2012 -s tb -o " + quote(executable) +
    " " + quote(tbPath) + " " + quote(dumped) +
    " " + quote(dumped.parent_path() / "naja_primitives.v");
  ASSERT_EQ(0, std::system(compile.c_str()));
  ASSERT_EQ(0, std::system(("vvp " + quote(executable)).c_str()));
  if (std::system("command -v verilator >/dev/null 2>&1") == 0) {
    const auto lint = "verilator --lint-only --sv --top-module wide_signed_index_reads " +
      quote(dumped) + " " + quote(dumped.parent_path() / "naja_primitives.v");
    EXPECT_EQ(0, std::system(lint.c_str()));
  }
}

class SNLSVTableSelectTest: public SNLSVConstructorTestSimple,
  public ::testing::WithParamInterface<std::tuple<size_t, size_t, bool>> {};

TEST_P(SNLSVTableSelectTest, packedIndexFourStateSimulation) {
  const auto [width, depth, ascending] = GetParam();
  const size_t abits = depth <= 4 ? 2 : 3;
  const auto testName = "table_select_w" + std::to_string(width) +
    "_d" + std::to_string(depth) + (ascending ? "_ascending" : "_descending");
  std::ostringstream source;
  source << "module " << testName << "(input logic ["
    << (ascending ? 0 : depth - 1) << ":" << (ascending ? depth - 1 : 0) << "]";
  if (width > 1) {
    source << "[" << width - 1 << ":0]";
  }
  source << " DATA, input logic [" << abits - 1 << ":0] ADDR, output logic ";
  if (width > 1) {
    source << "[" << width - 1 << ":0] ";
  }
  source << "Y);\n  assign Y = DATA[ADDR];\nendmodule\n";
  const auto svPath = writeSVTestFile(testName, source.str());
  SNLSVConstructor constructor(library_);
  constructor.construct(svPath);
  auto* top = library_->getSNLDesign(NLName(testName));
  ASSERT_NE(nullptr, top);
  EXPECT_EQ(1u, countTableSelectInstances(
    top, NLDB0::TableSelectSignature {width, depth, abits}));
  const auto dumpedPath = dumpTopAndGetVerilogPath(top, testName + "_dump");
  const auto primitivesPath = dumpedPath.parent_path() / "naja_primitives.v";
  ASSERT_TRUE(std::filesystem::exists(primitivesPath));

  if (std::system("command -v iverilog >/dev/null 2>&1") != 0 ||
      std::system("command -v vvp >/dev/null 2>&1") != 0) {
    GTEST_SKIP() << "Icarus Verilog is required for the four-state comparison";
  }

  // Simulate the original SV indexing alongside the lowered, dumped netlist.
  auto reference = source.str();
  reference.replace(reference.find(testName), testName.size(), "table_select_reference");
  const auto tbPath = svPath.parent_path() / "tb.sv";
  std::ofstream tb(tbPath);
  ASSERT_TRUE(tb.good());
  tb << reference << "module tb;\n"
    << "  localparam WIDTH = " << width << ", DEPTH = " << depth
    << ", ABITS = " << abits << ";\n"
    << "  reg [WIDTH*DEPTH-1:0] data;\n"
    << "  reg [ABITS-1:0] addr;\n"
    << "  wire [WIDTH-1:0] actual, expected;\n"
    << "  " << testName << " dut (.DATA(data), .ADDR(addr), .Y(actual));\n"
    << "  table_select_reference ref_index (.DATA(data), .ADDR(addr), .Y(expected));\n"
    << R"(  integer pattern, code, bit_index;
  initial begin
    // Identical rows catch accidental mux merging of unknown addresses;
    // mixed data also checks that valid reads preserve individual X/Z bits.
    for (pattern = 0; pattern < 5; pattern = pattern + 1) begin
      case (pattern)
        0: data = '0;
        1: data = '1;
        2: data = 'x;
        3: data = 'z;
        4: for (bit_index = 0; bit_index < WIDTH*DEPTH; bit_index = bit_index + 1)
          case ((bit_index + bit_index / WIDTH) % 4)
            0: data[bit_index] = 1'b0;
            1: data[bit_index] = 1'b1;
            2: data[bit_index] = 1'bx;
            3: data[bit_index] = 1'bz;
          endcase
      endcase
      // Exhaust every 0/1/X/Z address, including partially unknown and OOB.
      for (code = 0; code < (1 << (2*ABITS)); code = code + 1) begin
        for (bit_index = 0; bit_index < ABITS; bit_index = bit_index + 1)
          case ((code >> (2*bit_index)) & 3)
            0: addr[bit_index] = 1'b0;
            1: addr[bit_index] = 1'b1;
            2: addr[bit_index] = 1'bx;
            3: addr[bit_index] = 1'bz;
          endcase
        #1;
        if (actual !== expected)
          $fatal(1, "addr=%b data=%b actual=%b SV=%b", addr, data, actual, expected);
        // Check invalid-index semantics independently of the equivalence check.
        if (((^addr) === 1'bx) || addr >= DEPTH)
          if (expected !== {WIDTH{1'bx}})
            $fatal(1, "invalid packed index did not produce X: addr=%b SV=%b", addr, expected);
      end
    end
    $finish;
  end
endmodule
)";
  tb.close();
  const auto quotePath = [](const std::filesystem::path& path) {
    std::string quoted = "'";
    for (char c: path.string()) {
      quoted += c == '\'' ? "'\\''" : std::string(1, c);
    }
    return quoted + "'";
  };
  const auto executablePath = svPath.parent_path() / "simulation.vvp";
  const auto compile = "iverilog -g2012 -s tb -o " + quotePath(executablePath) +
    " " + quotePath(tbPath) + " " + quotePath(dumpedPath) + " " + quotePath(primitivesPath);
  ASSERT_EQ(0, std::system(compile.c_str()));
  ASSERT_EQ(0, std::system(("vvp " + quotePath(executablePath)).c_str()));
}

TEST_P(SNLSVTableSelectTest, constantPackedIndexFourStateSimulation) {
  const auto [width, depth, ascending] = GetParam();
  const size_t abits = depth <= 4 ? 2 : 3;
  const auto name = "constant_lookup_w" + std::to_string(width) + "_d" + std::to_string(depth) + (ascending ? "_asc" : "_desc");
  std::string image;
  for (size_t bit = 0; bit < width*depth; ++bit) image += "10xz"[bit%4];
  std::ostringstream source;
  source << "module " << name << "(input logic [" << abits-1 << ":0] A, output logic [" << width-1 << ":0] Y);\n"
    << "localparam logic [" << (ascending ? 0 : depth-1) << ":" << (ascending ? depth-1 : 0) << "]";
  if (width > 1) source << "[" << width-1 << ":0]";
  source << " DATA = " << width*depth << "'b" << image << ";\nassign Y = DATA[A]; endmodule\n";
  const auto path = writeSVTestFile(name, source.str());
  SNLSVConstructor(library_).construct(path);
  auto* top = library_->getSNLDesign(NLName(name));
  ASSERT_NE(top, nullptr);
  auto* rom = findOnlyPrimitiveInstance(top, NLDB0::isMemory);
  ASSERT_NE(rom, nullptr);
  EXPECT_EQ(0u, NLDB0::getMemorySignature(rom).writePorts);
  EXPECT_EQ(2u, rom->getModel()->getTerms().size());
  const auto dumped = dumpTopAndGetVerilogPath(top, name + "_dump");
  if (std::system("command -v iverilog >/dev/null 2>&1") || std::system("command -v vvp >/dev/null 2>&1"))
    GTEST_SKIP() << "Icarus Verilog is required for the ROM comparison";
  auto reference = source.str();
  reference.replace(reference.find(name), name.size(), "reference_lookup");
  // Icarus does not accept multidimensional packed localparams; a constant
  // wire preserves the reference array's layout and indexing semantics.
  reference.replace(reference.find("localparam logic"), 16, "wire");
  const auto tbPath = path.parent_path() / "tb.sv";
  std::ofstream tb(tbPath);
  tb << reference << "module tb; reg [" << abits-1 << ":0] a; wire [" << width-1 << ":0] actual, expected;\n"
    << name << " dut(a,actual); reference_lookup ref_index(a,expected); integer code, bit_index; initial begin\n"
    << "for(code=0;code<" << (1u << (2*abits)) << ";code=code+1) begin\n"
    << "for(bit_index=0;bit_index<" << abits << ";bit_index=bit_index+1)\n"
    << "case((code >> (2*bit_index)) & 3) 0:a[bit_index]=0; 1:a[bit_index]=1; 2:a[bit_index]=1'bx; 3:a[bit_index]=1'bz; endcase\n"
    << "#1; if(actual !== expected) $fatal(1,\"ROM mismatch: address=%b actual=%b expected=%b\",a,actual,expected);\n"
    << "end $finish; end endmodule\n";
  tb.close();
  const auto quote = [](const std::filesystem::path& value) {
    std::string result = "'";
    for (char c : value.string()) result += c == '\'' ? "'\\''" : std::string(1,c);
    return result + "'";
  };
  const auto executable = path.parent_path() / "simulation.vvp";
  const auto compile = "iverilog -g2012 -s tb -o " + quote(executable) + " " + quote(tbPath) + " " +
      quote(dumped) + " " + quote(dumped.parent_path() / "naja_primitives.v");
  ASSERT_EQ(0, std::system(compile.c_str()));
  ASSERT_EQ(0, std::system(("vvp " + quote(executable)).c_str()));
}

